\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
Fix a prime $p$, an algebraically closed field $k$ of characteristic $p$, and a finite $p$-group $P$. Among all finite groups $G$, are there only finitely many Morita-equivalence classes of blocks of $kG$ with defect group isomorphic to $P$?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2016/10}{[S2]}.

\subsection{Short English statement}
Fix a prime $p$, an algebraically closed field $k$ of characteristic $p$, and a finite $p$-group $P$. Among all finite groups $G$, are there only finitely many Morita-equivalence classes of blocks of $kG$ with defect group isomorphic to $P$?

\subsection{Sources}
\begin{itemize}
